BEGIN;

-- Ficha de La Materialista.
--
-- Campos: second_last_name Honoret (Impacto Latino, Diario Libre, Wikipedia es);
-- occupations actress (cuatro películas dominicanas, Wikipedia es con Hoy 2014).
-- Nombre y primer apellido quedan con la grafía de la fila (Yameyry Ynfante);
-- Wikipedia y Diario Libre escriben Yameiry Infante.
-- Fuera: Q Award 2012-2013 (sin referencia), acusación de plagio de 2013 (fuentes
-- de fans), vida personal, ingresos en otras plataformas.

UPDATE artists SET second_last_name = 'Honoret', occupations = '["actress"]'::jsonb WHERE slug = 'la-materialista';

